question:
I made a small C program that should print an emoji: 
 #include <stdio.h>
#include <windows.h>

int main(void) {
 SetConsoleOutputCP(CP_UTF8);
 printf("\U0001F625\n"); // 😥
 return 0;
}

 And it worked fine. But I wanted to try wprintf and wrote this program: 
 #include <stdio.h>

int main(void) {
 wprintf(L"\U0001F625\n"); // 😥
 return 0;
}

 But it didn't work. Why did it not work? 

 #include <stdio.h>
#include <windows.h>

int main(void) {
 SetConsoleOutputCP(CP_UTF8);
 printf("\U0001F625\n"); // 😥
 return 0;
}

 wprintf 
 #include <stdio.h>

int main(void) {
 wprintf(L"\U0001F625\n"); // 😥
